package com.cognia.api.adapter.out.persistence;
import com.cognia.api.application.port.out.ShortEvaluationRepository; import com.cognia.api.domain.model.*; import jakarta.persistence.EntityManager; import java.util.*; import org.springframework.stereotype.Repository; import org.springframework.transaction.annotation.Transactional;
@Repository @Transactional public class ShortEvaluationJpaRepositoryAdapter implements ShortEvaluationRepository {
	private final EntityManager em; public ShortEvaluationJpaRepositoryAdapter(EntityManager em){this.em=em;}
	public Optional<ShortEvaluation> inProgress(UUID student,UUID step){return em.createQuery("select s from DiagnosticSessionJpaEntity s where s.studentId=:student and s.pathStepId=:step and s.type='EVALUACION_CORTA' and s.state='EN_PROGRESO' order by s.id",DiagnosticSessionJpaEntity.class).setParameter("student",student).setParameter("step",step).setMaxResults(1).getResultList().stream().map(this::map).findFirst();}
	public Optional<ShortEvaluation> find(UUID id){return em.createQuery("select s from DiagnosticSessionJpaEntity s where s.id=:id and s.type='EVALUACION_CORTA'",DiagnosticSessionJpaEntity.class).setParameter("id",id).setMaxResults(1).getResultList().stream().map(this::map).findFirst();}
	public int nextAttempt(UUID student,UUID concept){var completedOrInProgress=em.createQuery("select count(s.id) from DiagnosticSessionJpaEntity s where s.studentId=:student and s.conceptId=:concept and s.type='EVALUACION_CORTA'",Long.class).setParameter("student",student).setParameter("concept",concept).getSingleResult();return Math.toIntExact(completedOrInProgress)+1;}
	public int consecutiveFailures(UUID student,UUID step){var recent=em.createQuery("select s.passed from DiagnosticSessionJpaEntity s where s.studentId=:student and s.pathStepId=:step and s.type='EVALUACION_CORTA' and s.state='COMPLETADA' order by s.closedAt desc",Boolean.class).setParameter("student",student).setParameter("step",step).setMaxResults(100).getResultList();var count=0;for(var passed:recent){if(Boolean.TRUE.equals(passed))break;if(Boolean.FALSE.equals(passed))count++;}return count;}
	public int reinforcementDifficulty(UUID student,UUID step){var sessions=em.createQuery("select s.id from DiagnosticSessionJpaEntity s where s.studentId=:student and s.pathStepId=:step and s.type='EVALUACION_CORTA' and s.state='COMPLETADA' and s.passed=false order by s.closedAt desc",UUID.class).setParameter("student",student).setParameter("step",step).setMaxResults(1).getResultList();if(sessions.isEmpty())return 1;var values=em.createQuery("select a.difficulty from DiagnosticAnswerJpaEntity r, ActivityJpaEntity a where r.sessionId=:session and a.id=r.activityId",Integer.class).setParameter("session",sessions.get(0)).getResultList();return values.stream().mapToInt(Integer::intValue).max().orElse(1);}
	public ShortEvaluation save(ShortEvaluation session){if(session.id()==null){var row=new DiagnosticSessionJpaEntity(session.studentId(),session.subjectId(),session.conceptId(),session.pathStepId(),session.attempt());em.persist(row);em.flush();return map(row);}var row=em.find(DiagnosticSessionJpaEntity.class,session.id());if(row==null||!row.getType().equals("EVALUACION_CORTA"))throw new IllegalArgumentException("Short evaluation was not found");if("COMPLETADA".equals(session.state()))row.complete(session.score(),Boolean.TRUE.equals(session.passed()),session.closedAt());return map(row);}
	public List<EvaluationAnswer> answers(UUID session){return em.createQuery("select a from DiagnosticAnswerJpaEntity a where a.sessionId=:id order by a.id",DiagnosticAnswerJpaEntity.class).setParameter("id",session).getResultList().stream().map(a->new EvaluationAnswer(null,session,a.getActivityId(),a.isCorrect())).toList();}
	public EvaluationAnswer saveAnswer(UUID session,UUID activity,UUID option,String text,boolean correct,Integer seconds){var row=new DiagnosticAnswerJpaEntity(session,activity,option,text,correct,seconds);em.persist(row);em.flush();return new EvaluationAnswer(row.getId(),session,activity,correct);}
	private ShortEvaluation map(DiagnosticSessionJpaEntity s){return new ShortEvaluation(s.getId(),s.getStudentId(),s.getSubjectId(),s.getConceptId(),s.getPathStepId(),s.getAttempt(),s.getState(),s.getClosedAt(),s.getScore(),s.getPassed());}
}
